import React, { useState } from 'react';
import { Loader, Play, Radio } from 'lucide-react';
import { getSimulate } from '../services/api';
import EventCard from '../components/EventCard';

export default function Events() {
  const [events, setEvents] = useState([]);
  const [loading, setLoading] = useState(false);
  const [filter, setFilter] = useState('all');

  const simulate = async () => {
    setLoading(true);
    try {
      const r = await getSimulate(20, 8);
      setEvents(r.data.events);
    } catch {
      alert('Backend not reachable. Start FastAPI on port 8000.');
    } finally {
      setLoading(false);
    }
  };

  const filtered = filter === 'all' ? events : events.filter(e => e.action === filter || e.risk === filter);

  return (
    <div className="space-y-5">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-xl font-bold text-gray-800">Live Traffic Events</h2>
          <p className="text-sm text-gray-500">Simulated website traffic each event explained by SHAP & LIME</p>
        </div>
        <button
          onClick={simulate}
          disabled={loading}
          className="bg-blue-700 hover:bg-blue-800 text-white px-4 py-2 rounded-lg text-sm font-medium disabled:opacity-50"
        >
          {loading ? '⏳ Simulating...' : '▶ Run Simulation'}
        </button>
      </div>

      {events.length > 0 && (
        <div className="flex gap-2 flex-wrap">
          {['all', 'blocked', 'flagged', 'allowed', 'critical', 'high'].map(f => (
            <button
              key={f}
              onClick={() => setFilter(f)}
              className={`px-3 py-1 rounded-full text-xs font-medium border transition-colors ${
                filter === f ? 'bg-blue-700 text-white border-blue-700' : 'bg-white text-gray-600 border-gray-300 hover:border-blue-400'
              }`}
            >
              {f.charAt(0).toUpperCase() + f.slice(1)}
            </button>
          ))}
          <span className="text-xs text-gray-400 self-center ml-2">{filtered.length} events</span>
        </div>
      )}

      {events.length === 0 && !loading && (
        <div className="bg-white rounded-xl shadow p-12 text-center text-gray-400">
          <div className="text-5xl mb-3">📡</div>
          <p className="text-lg font-medium">No events yet</p>
          <p className="text-sm mt-1">Click "Run Simulation" to generate traffic data</p>
        </div>
      )}

      <div className="space-y-3">
        {filtered.map(e => <EventCard key={e.id} event={e} />)}
      </div>
    </div>
  );
}
